const form = document.querySelector(".top form");
const box = document.querySelector("#q");
const hits = document.querySelector(".hits");
let cursor = -1;
function go(item) { if (item) location.href = item.href; }
const pre = "../".repeat(Number(document.documentElement.dataset.depth || 0));
function show(q) {
  hits.innerHTML = "";
  cursor = -1;
  q = q.trim().toLowerCase();
  if (!q) return;
  const found = INDEX.filter(r => (r.t + " " + r.d + " " + r.g).toLowerCase().includes(q)).slice(0, 12);
  for (const r of found) {
    const li = document.createElement("li");
    const a = document.createElement("a");
    a.href = pre + r.u;
    a.textContent = r.t + "  " + r.g;
    li.appendChild(a);
    hits.appendChild(li);
  }
}
if (box) {
  box.addEventListener("input", () => show(box.value));
  box.addEventListener("keydown", (ev) => {
    const links = [...hits.querySelectorAll("a")];
    if (ev.key === "ArrowDown" || ev.key === "ArrowUp") {
      ev.preventDefault();
      cursor = Math.max(0, Math.min(links.length - 1, cursor + (ev.key === "ArrowDown" ? 1 : -1)));
      links.forEach((a, i) => a.classList.toggle("on", i === cursor));
    } else if (ev.key === "Enter") {
      ev.preventDefault();
      go(links[cursor] || links[0]);
    } else if (ev.key === "Escape") hits.innerHTML = "";
  });
}
document.addEventListener("click", (ev) => { if (!form.contains(ev.target)) hits.innerHTML = ""; });
